import os, collections
ROOT="AlgebraicJacobian"
def path2mod(p): return p[:-5].replace('/','.')
imports=collections.defaultdict(set); mods=set()
for dp,dn,fn in os.walk(ROOT):
    for f in fn:
        if not f.endswith('.lean'): continue
        p=os.path.join(dp,f); m=path2mod(p); mods.add(m)
        for line in open(p):
            if line.startswith('import AlgebraicJacobian'):
                imports[m].add(line.split()[1].strip())
NEW=['AlgebraicJacobian.RiemannRoch.Ledger.OrdCompare',
     'AlgebraicJacobian.RiemannRoch.Ledger.ResidueOneAlgClosed',
     'AlgebraicJacobian.RiemannRoch.Adelic.FiniteMapToP1']
W='AlgebraicJacobian.RiemannRoch.WeilDivisor'
imports[W] |= set(NEW)
# full cycle detection (Tarjan-lite via DFS colors)
color={}; cyc=[]
def dfs(u, stack):
    color[u]=1
    for v in imports.get(u,()):
        if color.get(v)==1:
            cyc.append(stack+[u,v]); 
        elif color.get(v) is None:
            dfs(v, stack+[u])
    color[u]=2
for m in sorted(mods):
    if color.get(m) is None: dfs(m,[])
print("CYCLES FOUND:", len(cyc))
for c in cyc[:5]: print("  ", " -> ".join(x.split('.')[-1] for x in c))
def cone(m):
    seen=set(); st=[m]
    while st:
        x=st.pop()
        if x in seen: continue
        seen.add(x); st.extend(imports.get(x,()))
    return seen
print("new WeilDivisor cone:", len(cone(W)))
print("root cone:", len(cone('AlgebraicJacobian')))
EOF
